Here is the commit message:
crypto: caam - fix error return code in caam_qi_init()
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Fix to return error code -ENOMEM from the kmem_cache_create() error
handling case instead of 0(err is 0 here), as done elsewhere in this
function.

Fixes: 67c2315def06 ("crypto: caam - add Queue Interface (QI) backend support")
Signed-off-by: Wei Yongjun <weiyongjun1@huawei.com>
Acked-by: Horia Geantă <horia.geanta@nxp.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug was caused by returning a success status (0) instead of an appropriate error code (-ENOMEM) when the `kmem_cache_create()` function failed. This misrepresentation of the error state could lead to incorrect assumptions about the successful initialization of the Queue Interface (QI), potentially causing further issues in the system that relies on this initialization.

Here is the patch:

 int caam_qi_init(struct platform_device *caam_pdev)
 {
 	int err, i;
 	struct platform_device *qi_pdev;
 	struct device *ctrldev = &caam_pdev->dev, *qidev;
 	struct caam_drv_private *ctrlpriv;
 	const cpumask_t *cpus = qman_affine_cpus();
 	struct cpumask old_cpumask = current->cpus_allowed;
 	static struct platform_device_info qi_pdev_info = {
 		.name = "caam_qi",
 		.id = PLATFORM_DEVID_NONE
 	};

 	/*
 	 * QMAN requires CGRs to be removed from same CPU+portal from where it
 	 * was originally allocated. Hence we need to note down the
 	 * initialisation CPU and use the same CPU for module exit.
 	 * We select the first CPU to from the list of portal owning CPUs.
 	 * Then we pin module init to this CPU.
 	 */
 	mod_init_cpu = cpumask_first(cpus);
 	set_cpus_allowed_ptr(current, get_cpu_mask(mod_init_cpu));

 	qi_pdev_info.parent = ctrldev;
 	qi_pdev_info.dma_mask = dma_get_mask(ctrldev);
 	qi_pdev = platform_device_register_full(&qi_pdev_info);
 	if (IS_ERR(qi_pdev))
 		return PTR_ERR(qi_pdev);

 	ctrlpriv = dev_get_drvdata(ctrldev);
 	qidev = &qi_pdev->dev;

 	qipriv.qi_pdev = qi_pdev;
 	dev_set_drvdata(qidev, &qipriv);

 	/* Initialize the congestion detection */
 	err = init_cgr(qidev);
 	if (err) {
 		dev_err(qidev, "CGR initialization failed: %d\n", err);
 		platform_device_unregister(qi_pdev);
 		return err;
 	}

 	/* Initialise response FQs */
 	err = alloc_rsp_fqs(qidev);
 	if (err) {
 		dev_err(qidev, "Can't allocate CAAM response FQs: %d\n", err);
 		free_rsp_fqs();
 		platform_device_unregister(qi_pdev);
 		return err;
 	}

 	/*
 	 * Enable the NAPI contexts on each of the core which has an affine
 	 * portal.
 	 */
 	for_each_cpu(i, cpus) {
 		struct caam_qi_pcpu_priv *priv = per_cpu_ptr(&pcpu_qipriv, i);
 		struct caam_napi *caam_napi = &priv->caam_napi;
 		struct napi_struct *irqtask = &caam_napi->irqtask;
 		struct net_device *net_dev = &priv->net_dev;

 		net_dev->dev = *qidev;
 		INIT_LIST_HEAD(&net_dev->napi_list);

 		netif_napi_add(net_dev, irqtask, caam_qi_poll,
 			       CAAM_NAPI_WEIGHT);

 		napi_enable(irqtask);
 	}

 	/* Hook up QI device to parent controlling caam device */
 	ctrlpriv->qidev = qidev;

 	qi_cache = kmem_cache_create("caamqicache", CAAM_QI_MEMCACHE_SIZE, 0,
 				     SLAB_CACHE_DMA, NULL);
 	if (!qi_cache) {
 		dev_err(qidev, "Can't allocate CAAM cache\n");
 		free_rsp_fqs();
 		platform_device_unregister(qi_pdev);
-		return err;
+		return -ENOMEM;
 	}

 	/* Done with the CGRs; restore the cpus allowed mask */
 	set_cpus_allowed_ptr(current, &old_cpumask);
 #ifdef CONFIG_DEBUG_FS
 	ctrlpriv->qi_congested = debugfs_create_file("qi_congested", 0444,
 						     ctrlpriv->ctl,
 						     &times_congested,
 						     &caam_fops_u64_ro);
 #endif
 	dev_info(qidev, "Linux CAAM Queue I/F driver initialised\n");
 	return 0;
 }
